import json,base64,pathlib,html
p=pathlib.Path(__file__).parent;a=p/'artifacts'
metrics=json.loads((a/'ablation_results.json').read_text());examples=json.loads((a/'examples.json').read_text())
rows=[]
for name,v in metrics['variants'].items():
 m=v['metrics'];rows.append(f'<tr><td>{html.escape(name)}</td><td>{m["mse"]:.5f}</td><td>{m["changed_mse"]:.5f}</td><td>{m["static_mse"]:.5f}</td><td>{m["dam_presence_accuracy"]:.1%}</td><td>{v["parameters"]:,}</td></tr>')
img=base64.b64encode((a/'ablation_comparison.png').read_bytes()).decode()
js=json.dumps(examples,separators=(',',':'))
s=f'''<!doctype html><html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EchoWorld v3 | Visual Dynamics Ablation</title><style>body{{font:15px system-ui;background:#0e1726;color:#edf4fa;max-width:1150px;margin:auto;padding:30px}}h1{{font-size:28px}}p,small{{color:#b0c3d5;line-height:1.7}}section{{background:#17243a;border:1px solid #31435a;border-radius:16px;padding:20px;margin:18px 0}}table{{width:100%;border-collapse:collapse;font-size:13px}}th,td{{padding:12px;text-align:left;border-bottom:1px solid #31435a}}th{{color:#9ec6e7}}select{{background:#20334d;color:white;padding:10px;border-radius:8px;border:1px solid #4c6c89}}canvas{{width:256px;height:256px;image-rendering:pixelated;background:#213447;border-radius:8px}}.comparison{{display:flex;gap:14px;flex-wrap:wrap}}.tile{{display:flex;flex-direction:column;gap:8px}}.tile strong{{font-size:13px}}.scroll{{overflow-x:auto}}.muted{{color:#a4c6dc}}img{{max-width:100%}}</style></head><body><small>ECHOWORLD · REPRODUCIBLE EXPERIMENT</small><h1>Action-conditioned Visual Dynamics · v3</h1><p>真实 PyTorch 训练后的独立测试集消融：直接 CNN、残差 CNN、变化区域加权损失、4 帧 ConvGRU 与复制上一帧基线。模型在模拟器合成的 32×32 RGB 画面上学习，非 Genie 模型，也未接入真实游戏画面数据。</p><section><h2>模型定量消融</h2><p>整体 MSE 越小越好；变化区域 MSE 只计算真实画面发生变化的像素；物体显现准确率为固定区域 RGB 阈值检测代理指标，不能替代感知模型或人工标注评测。</p><div class="scroll"><table><tr><th>模型</th><th>整体 MSE ↓</th><th>变化区域 MSE ↓</th><th>静止区域 MSE ↓</th><th>水坝出现检测准确率 ↑</th><th>参数量</th></tr>{''.join(rows)}</table></div><p>训练 {metrics['data']['train_samples']} 个样本（20 回合，含变化采样）；验证 {metrics['data']['val_samples']} 个样本（5 回合）；测试 {metrics['data']['test_samples']} 个样本（8 回合）；每个模型训练 2 Epoch。各组共享测试样本，但不同模型存在优化器和架构差异。数据规模不足以证明统计显著性。</p></section><section><h2>交互式预测对比</h2><label>动作 <select id="action"></select></label> <label>模型 <select id="variant"></select></label><div class="comparison"><div class="tile"><strong>输入帧</strong><canvas id="input" width="32" height="32"></canvas></div><div class="tile"><strong>真实下一帧</strong><canvas id="truth" width="32" height="32"></canvas></div><div class="tile"><strong>模型预测</strong><canvas id="pred" width="32" height="32"></canvas></div></div><p>可视化的是训练完成后导出的模型真实预测，而不是在浏览器重新推理。逐像素对比有助于发现生成模糊、物体消失和不合理的环境变化。</p></section><section><h2>完整对照图</h2><img alt="all models comparisons" src="data:image/png;base64,{img}"></section><section><h2>结论与限制</h2><p>在这一轮小样本实验中，Residual CNN 改善了总体 MSE，但并不显著优于复制帧；加权损失和 ConvGRU 更倾向减少变化区域误差，却可能破坏静态区域。需要增加训练样本、长期滚动评测、视觉标注检测与多种随机种子验证，才能判断改进是否稳健。</p><p>数据标签来自确定性规则渲染器，没有真实物理世界的随机性；固定场景布局可能使阈值检测高估物体恒存能力。多帧 ConvGRU 使用 4 帧历史，但目前只训练单步输出，并非完整长序列视频生成器。</p></section><script>const examples={js};const a=document.getElementById('action'),v=document.getElementById('variant');examples.forEach((x,i)=>{{const o=document.createElement('option');o.value=i;o.textContent=x.action;a.append(o)}});const names=Object.keys(examples[0].images).filter(x=>!['Input','Ground truth'].includes(x));names.forEach(x=>{{const o=document.createElement('option');o.value=x;o.textContent=x;v.append(o)}});v.value='residual';function draw(id,data){{const c=document.getElementById(id),ctx=c.getContext('2d'),im=ctx.createImageData(32,32);for(let i=0;i<1024;i++){{im.data[4*i]=data[3*i];im.data[4*i+1]=data[3*i+1];im.data[4*i+2]=data[3*i+2];im.data[4*i+3]=255}}ctx.putImageData(im,0,0)}}function change(){{const images=examples[Number(a.value)].images;draw('input',images['Input']);draw('truth',images['Ground truth']);draw('pred',images[v.value])}}a.onchange=change;v.onchange=change;change();</script></body></html>'''
(p/'EchoWorld_v3_Visual_Lab.html').write_text(s)
